import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { pathToFileURL } from 'node:url';
const [repo, requestPath, outputPath] = process.argv.slice(2);
const request = JSON.parse(fs.readFileSync(requestPath));
const imp = p => import(pathToFileURL(path.join(repo, p)));
const { parseSurf } = await imp('packages/cadgen-js/src/lib/surf/container.js');
const { tessellateComponent, DEFAULT_OPTIONS, TESSELLATION_VERSION } = await imp('packages/cadgen-js/src/lib/surf/tessellate.js');
const { encodeComponentTessellation, edgeClassesFromSurfIndex } = await imp('packages/cadgen-js/src/lib/surf/tessellationCache.js');
const sha = x => crypto.createHash('sha256').update(x).digest('hex');
const t0 = performance.now();
const raw = fs.readFileSync(request.surf);
if (sha(raw) !== request.surfSha256) throw new Error('Changed SURF');
const t1 = performance.now();
const parsed = parseSurf(raw.buffer.slice(raw.byteOffset, raw.byteOffset + raw.byteLength));
const t2 = performance.now();
const options = { ...DEFAULT_OPTIONS, chordTolerance: 1.5e-4, angleTolerance: 0.35 };
const mesh = tessellateComponent(parsed.index, parsed.floats, options);
const t3 = performance.now();
const encoded = encodeComponentTessellation(mesh, { edgeClasses: edgeClassesFromSurfIndex(parsed.index), partColor: parsed.index.partColor ?? null });
const t4 = performance.now();
fs.writeFileSync(request.jsTess, encoded);
const result = { cid: request.cid, options, tessellationVersion: TESSELLATION_VERSION,
  scale: mesh.scale, absoluteChordMm: mesh.scale * options.chordTolerance,
  faceCount: parsed.index.faces.length, edgeCount: parsed.index.edges.length,
  vertices: mesh.positions.length / 3, triangles: mesh.indices.length / 3,
  encodedBytes: encoded.length, encodedSha256: sha(encoded),
  stagesMs: { readVerify: t1-t0, parse: t2-t1, mesh: t3-t2, encode: t4-t3 },
  peakRssBytes: process.resourceUsage().maxRSS * 1024,
};
fs.writeFileSync(outputPath, JSON.stringify(result, null, 2));
